(6590376, 983061, 124982, '<td valign="top">Easily the winner in this challenge for me!</td>', 'Easily the winner in this challenge for me!', '2011-11-09 08:25:42.000000', NULL, 1),
(6590377, 982947, 113278, '<td valign="top">Absolutely brilliant. The tones are amazing and the flow is spectacular. If I were to guess this has a bit of a feel of a BearMusic shot.</td>', 'Absolutely brilliant. The tones are amazing and the flow is spectacular. If I were to guess this has a bit of a feel of a BearMusic shot.', '2011-11-09 08:26:49.000000', NULL, 1),
(6590381, 983152, 93565, '<td valign="top">This would''ve been a great entry in the Weston Challenge we had awhile back. I''m less fond of the shots that are strictly still lifes of whatever naturally occuring examples there are of phi, but this one really is done splendidly.  Nice job, one of my tops.</td>', 'This would''ve been a great entry in the Weston Challenge we had awhile back. I''m less fond of the shots that are strictly still lifes of whatever naturally occuring examples there are of phi, but this one really is done splendidly.  Nice job, one of my tops.', '2011-11-09 08:28:19.000000', NULL, 1),
(6590386, 982978, 113278, '<td valign="top">Stunning light and bokeh.</td>', 'Stunning light and bokeh.', '2011-11-09 08:29:19.000000', NULL, 1),
(6590387, 982900, 93565, '<td valign="top">Shots like this really demand sharper detail than you''ve managed here. Stopping down will help you with shots like this, as well increasing your contrast. You do have some cross lighting working to help define things, but it could be exaggerated more.</td>', 'Shots like this really demand sharper detail than you''ve managed here. Stopping down will help you with shots like this, as well increasing your contrast. You do have some cross lighting working to help define things, but it could be exaggerated more.', '2011-11-09 08:30:23.000000', NULL, 1),
(6590388, 982356, 113278, '<td valign="top">Poignant shot. just stunning and an excellent use of the ratio.</td>', 'Poignant shot. just stunning and an excellent use of the ratio.', '2011-11-09 08:30:56.000000', NULL, 1),
(6590390, 982960, 113278, '<td valign="top">Good luck</td>', 'Good luck', '2011-11-09 08:31:50.000000', NULL, 1),
