(6590820, 982864, 12611, '<td valign="top">Great shadow- it just creates a huge presence in the shot. a compositional arrow.</td>', 'Great shadow- it just creates a huge presence in the shot. a compositional arrow.', '2011-11-09 16:48:40.000000', NULL, 1),
(6590823, 983039, 12611, '<td valign="top">I am interested but a bit overwhelmed. The contrast is undeniably perfect, though.</td>', 'I am interested but a bit overwhelmed. The contrast is undeniably perfect, though.', '2011-11-09 16:50:27.000000', NULL, 1),
(6590825, 983105, 12611, '<td valign="top">Great negative space. I am not usually a fan of bird shot, they seem cold and lizard-like; but your take on a swan shot, or the golden ratio, has drawn me in.</td>', 'Great negative space. I am not usually a fan of bird shot, they seem cold and lizard-like; but your take on a swan shot, or the golden ratio, has drawn me in.', '2011-11-09 16:51:38.000000', NULL, 1),
(6590826, 983135, 12611, '<td valign="top">The shadows on the legs are nice, and the color and composition help overcome the tightest of crops.</td>', 'The shadows on the legs are nice, and the color and composition help overcome the tightest of crops.', '2011-11-09 16:53:04.000000', NULL, 1),
