(6590835, 983094, 12611, '<td valign="top">My type of shot! black and white is perfect, the contrast and juxtaposition between far and near boats creates interest, and the noisy grainy feel is an old familiar friend. The border must have been a tough choice, but it works. 9</td>', 'My type of shot! black and white is perfect, the contrast and juxtaposition between far and near boats creates interest, and the noisy grainy feel is an old familiar friend. The border must have been a tough choice, but it works. 9', '2011-11-09 16:58:45.000000', NULL, 1),
(6590837, 983037, 12611, '<td valign="top">Dreamy, yet glare filled and way too in focus-the textures, the shadows, these add to the dream, and I am pulled toward the lavender umbrella, beckoned to descend the dreamy golden nautilus. My favorite. 10</td>', 'Dreamy, yet glare filled and way too in focus-the textures, the shadows, these add to the dream, and I am pulled toward the lavender umbrella, beckoned to descend the dreamy golden nautilus. My favorite. 10', '2011-11-09 17:01:19.000000', NULL, 1),
