INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6593451, 983133, 114225, '<td valign="top">Beautiful use of silhouette.</td>', 'Beautiful use of silhouette.', '2011-11-13 08:54:11.000000', NULL, 1),
(6593499, 982325, 114225, '<td valign="top">Oh, I like this. The details of instruments can be so interesting, and the way you lit this enhances that.</td>', 'Oh, I like this. The details of instruments can be so interesting, and the way you lit this enhances that.', '2011-11-13 11:03:55.000000', NULL, 1),
(6593500, 983062, 114225, '<td valign="top">Intriguing shot.  I''m not sure I would have ever composed like this, but it seems to work well.</td>', 'Intriguing shot.  I''m not sure I would have ever composed like this, but it seems to work well.', '2011-11-13 11:04:25.000000', NULL, 1),
(6593501, 983151, 114225, '<td valign="top">It''s very cool how the bridge and reflection join together at the end.</td>', 'It''s very cool how the bridge and reflection join together at the end.', '2011-11-13 11:06:00.000000', NULL, 1),
(6593502, 982960, 114225, '<td valign="top">Great eye. The depth of field is very pleasing for this shot.</td>', 'Great eye. The depth of field is very pleasing for this shot.', '2011-11-13 11:06:43.000000', NULL, 1),
(6593504, 983113, 49018, '<td valign="top">Interesting photograph, the golden spiral is the most enticing pattern related to the golden ratio. I am not sure if the hand adds or detracts from the shot, in particular the blue cable. I would find it more interesting if the pose of the hand would more explicitly appear like having just thrown the marbles in this magic arc. Also, I personally find the the golden spiral more suggestive when it touches the borders of the frame, so maybe cropping tighter to exclude the hand or use lightpainting to draw a frame around the marbles would have worked better for me.</td>', 'Interesting photograph, the golden spiral is the most enticing pattern related to the golden ratio. I am not sure if the hand adds or detracts from the shot, in particular the blue cable. I would find it more interesting if the pose of the hand would more explicitly appear like having just thrown the marbles in this magic arc. Also, I personally find the the golden spiral more suggestive when it touches the borders of the frame, so maybe cropping tighter to exclude the hand or use lightpainting to draw a frame around the marbles would have worked better for me.', '2011-11-13 11:07:34.000000', NULL, 1),
(6593506, 983079, 114225, '<td valign="top">Fantastic job with the lighting to highlight all the right places.</td>', 'Fantastic job with the lighting to highlight all the right places.', '2011-11-13 11:07:42.000000', NULL, 1),
(6593508, 982486, 114225, '<td valign="top">Great portrait. The B&amp;W is very nice.</td>', 'Great portrait. The B&W is very nice.', '2011-11-13 11:09:38.000000', NULL, 1),
(6593509, 983060, 49018, '<td valign="top">Well spotted. Maybe an angle emphasizing further the spiral pattern would have worked better while introducing some more interesting pattern in the otherwise good bokeh.</td>', 'Well spotted. Maybe an angle emphasizing further the spiral pattern would have worked better while introducing some more interesting pattern in the otherwise good bokeh.', '2011-11-13 11:10:03.000000', NULL, 1),
(6593510, 982669, 49018, '<td valign="top">Funny pun. Maybe a tad underexposed , which desaturates the yellow and loses a bit of detail in the leaves.</td>', 'Funny pun. Maybe a tad underexposed , which desaturates the yellow and loses a bit of detail in the leaves.', '2011-11-13 11:10:26.000000', NULL, 1),
(6593511, 982947, 49018, '<td valign="top">Very nice black and white.</td>', 'Very nice black and white.', '2011-11-13 11:10:44.000000', NULL, 1),
(6593512, 983156, 114225, '<td valign="top">Interesting observation, my eyes were directly drawn to the border, and then made their way into the photo. This isn''t a good thing, in my opinion. Maybe if the border were subdued a bit more, it wouldn''t stick out so much.</td>', 'Interesting observation, my eyes were directly drawn to the border, and then made their way into the photo. This isn''t a good thing, in my opinion. Maybe if the border were subdued a bit more, it wouldn''t stick out so much.', '2011-11-13 11:11:29.000000', NULL, 1),
(6593514, 983081, 114225, '<td valign="top">This is pretty cool. Reminds me of "Starry Night" by Van Gogh.</td>', 'This is pretty cool. Reminds me of "Starry Night" by Van Gogh.', '2011-11-13 11:13:01.000000', NULL, 1),
(6593515, 982501, 114225, '<td valign="top">Adorable! The depth of field and colors highlight your subject perfectly.</td>', 'Adorable! The depth of field and colors highlight your subject perfectly.', '2011-11-13 11:13:39.000000', NULL, 1),
(6593517, 983073, 114225, '<td valign="top">This is lit and setup so well. Was a marvelous image.</td>', 'This is lit and setup so well. Was a marvelous image.', '2011-11-13 11:15:31.000000', NULL, 1),
(6593518, 982819, 114225, '<td valign="top">Wow! This is so cool!</td>', 'Wow! This is so cool!', '2011-11-13 11:16:01.000000', NULL, 1),
(6593563, 982678, 114225, '<td valign="top">Very powerful photograph.</td>', 'Very powerful photograph.', '2011-11-13 11:58:40.000000', NULL, 1),
(6593565, 982405, 114225, '<td valign="top">A really sweet portrait.</td>', 'A really sweet portrait.', '2011-11-13 12:00:12.000000', NULL, 1),
(6593645, 983066, 117804, '<td valign="top">the colors seem washed out and whites blown away... too bad it could have been a great idea</td>', 'the colors seem washed out and whites blown away... too bad it could have been a great idea', '2011-11-13 14:25:01.000000', NULL, 1),
(6593732, 983080, 49018, '<td valign="top">I like it, funny take on the theme and on the fact that the golden spiral is found in many natural patterns. The only thing is that the golden spiral suggest me an inward movement. In this case from the top left corner to the spot where the egg is. I wonder how it would have worked to put the egg ( or some fragments of it suggesting the rest is out of the frame)  on the top-left corner, invert the direction of the footprints and put something else in place of the egg ( a real chick maybe? or a KFC drumstick. uhh.. no better not.. somebody might resent) or even nothing at all. Good image, well lit.</td>', 'I like it, funny take on the theme and on the fact that the golden spiral is found in many natural patterns. The only thing is that the golden spiral suggest me an inward movement. In this case from the top left corner to the spot where the egg is. I wonder how it would have worked to put the egg ( or some fragments of it suggesting the rest is out of the frame)  on the top-left corner, invert the direction of the footprints and put something else in place of the egg ( a real chick maybe? or a KFC drumstick. uhh.. no better not.. somebody might resent) or even nothing at all. Good image, well lit.', '2011-11-13 17:25:15.000000', NULL, 1),
(6593733, 982405, 49018, '<td valign="top">The tenderness is evident. I would have liked to be able to see a bit more of her face. The rimlight works well defining her figure against the background.</td>', 'The tenderness is evident. I would have liked to be able to see a bit more of her face. The rimlight works well defining her figure against the background.', '2011-11-13 17:25:55.000000', NULL, 1),
(6593769, 983131, 49018, '<td valign="top">I guess its'' just my taste, and some will find the increasing density of the spiral of shadow enticing, but I wonder if a bit more fill light from the right would not have worked better. Also, a closer crop on the spiral could have delayed of an instant understanding that this is actually a shell. But again, tha''t just my opinion.</td>', 'I guess its'' just my taste, and some will find the increasing density of the spiral of shadow enticing, but I wonder if a bit more fill light from the right would not have worked better. Also, a closer crop on the spiral could have delayed of an instant understanding that this is actually a shell. But again, tha''t just my opinion.', '2011-11-13 19:15:09.000000', NULL, 1),
(6594310, 983080, 86218, '<td valign="top">Cute take on this challenge and certainly one of my favourites. Top 5 for me 8</td>', 'Cute take on this challenge and certainly one of my favourites. Top 5 for me 8', '2011-11-14 02:12:15.000000', NULL, 1),
